mapper.select:
SELECT g.goods_id AS goodsId, g.user_id AS userId, g.goods_desc AS goodsDesc, g.price, g.original_price AS originalPrice, g.tags, g.create_time AS createTime FROM favourite f INNER JOIN goods g ON f.item_id = g.goods_id
f.user_id = #{currentUserId}
AND g.create_time >= #{param.beginTime}
AND g.create_time < DATE_ADD(#{param.endTime}, INTERVAL 1 DAY)
ORDER BY ${param.sortRules}
ORDER BY f.create_time DESC
